// Set dryRun to false to create the jobs for real.
// onlyTab / rowFrom / rowTo limit the run to specific sheet rows (blank = all).
// Rows picked this way skip the 2025+ date check.
return [{ json: { dryRun: true, onlyTab: '', rowFrom: 0, rowTo: 0 } }];

// Visible client tabs only - the pivot/summary tabs are not job lists.
var EXCLUDE=['summary','to be quoted','approved works','works completed'];
var only=String($('Settings').first().json.onlyTab||'').trim().toLowerCase();
return ($('List Worksheets').first().json.value||[]).filter(function(s){var n=String(s.name).trim().toLowerCase();return s.visibility==='Visible'&&EXCLUDE.indexOf(n)<0&&(!only||n===only);}).map(function(s){return {json:{id:s.id,name:String(s.name).trim()}};});

function S(v){return v==null?'':String(v).trim();}
function norm(s){return S(s).toLowerCase().replace(/[^a-z0-9]/g,'');}
function toDate(v){
  if(v===''||v==null)return null;
  if(typeof v==='number'&&v>20000&&v<80000){return new Date(Math.round((v-25569)*86400000));}
  var s=String(v).trim();var m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if(m){var y=+m[3];if(y<100)y+=2000;return new Date(Date.UTC(y,+m[2]-1,+m[1]));}
  var d=new Date(s);return isNaN(d)?null:d;
}
function colL(n){var s='';while(n>0){var r=(n-1)%26;s=String.fromCharCode(65+r)+s;n=Math.floor((n-1)/26);}return s;}
function colN(s){var n=0;for(var i=0;i<s.length;i++)n=n*26+(s.charCodeAt(i)-64);return n;}
var CUTOFF=new Date(Date.UTC(2025,0,1));
var SET=$('Settings').first().json;var RF=+SET.rowFrom||0,RT=+SET.rowTo||0;
// Only these sheet statuses go to ServiceM8: [ServiceM8 status, folder]. 'Equiry' is a sheet typo for Enquiry.
var STATUS={enquiry:['Quote','Enquiry'],equiry:['Quote','Enquiry'],estimated:['Quote','Estimated'],onhold:['Quote','On Hold'],approved:['Work Order','Approved'],partapproved:['Work Order','Part Approved'],reactivecallout:['Work Order','Reactive (Call-Out)']};
// Misspelt client names on the sheet -> one ServiceM8 client.
var CLIENT_ALIAS={zzclientf:'ZZ Client F',zzclientgschool:'ZZ Client G School'};
var queues={};$('SM8 Queues').all().forEach(function(i){if(i.json.uuid&&i.json.active==1)queues[norm(i.json.name)]=i.json.uuid;});
var clients={};$('SM8 Clients').all().forEach(function(i){if(i.json.uuid)clients[norm(i.json.name)]={uuid:i.json.uuid,name:i.json.name,address:S(i.json.address).replace(/\s*\n\s*/g,', ').replace(/,\s*,/g,',')};});
var existingPO={};$('SM8 Jobs').all().forEach(function(i){var p=S(i.json.purchase_order_number);if(p&&i.json.active==1)existingPO[p.toLowerCase()]={no:S(i.json.generated_job_id),uuid:S(i.json.uuid)};});
var tabs=$('Client Tabs').all().map(function(i){return i.json;});
// Client - Site naming. Tabs where the tab is the client and the cell is the site.
var PREFIX={'ZZ Client A':'ZZ Client A','ZZ Client B':'ZZ Client B','ZZ Client P':'ZZ Client P'};
function clientName(tab,site){
  site=S(site).replace(/\s+/g,' ');
  var p=PREFIX[tab];
  if(p){
    var rest=site;
    if(rest.toLowerCase().indexOf(p.toLowerCase())===0)rest=rest.slice(p.length).replace(/^[\s\-]+/,'');
    if(p==='ZZ Client A'&&/^mk$/i.test(rest))rest='Sampletown A';
    if(p==='ZZ Client P')rest=rest.replace(/^zz client a\s*-?\s*mk$/i,'ZZ Client A - Site 2').replace(/^zz client a\s+/i,'ZZ Client A ');
    return rest?p+' - '+rest:p;
  }
  if(tab==='ZZ Client C')return 'ZZ Client C';
  var name=site||tab;
  return CLIENT_ALIAS[norm(name)]||name;
}
var rows=[],skipped={},problems=[],newClients={},seen={},noDesc=[],writeOnly=[],inRange=[];
function count(k){skipped[k]=(skipped[k]||0)+1;}
$input.all().forEach(function(item,idx){
  var t=tabs[idx]||{};var tab=S(t.name);var r=item.json;var values=r.values||[];
  if(!values.length||!r.address){problems.push(tab+': could not read the tab');return;}
  var ref=String(r.address).split('!').pop();var m=ref.split(':')[0].match(/([A-Z]+)(\d+)/);var c0=colN(m[1]),r0=parseInt(m[2],10);
  var hi=-1;for(var k=0;k<Math.min(values.length,10);k++){var nr=values[k].map(norm);if(nr.indexOf('status')>=0&&nr.indexOf('description')>=0){hi=k;break;}}
  if(hi<0){problems.push(tab+': no Status + Description header row, tab skipped');return;}
  var H=values[hi].map(norm);
  function col(al){for(var a=0;a<al.length;a++){var j=H.indexOf(norm(al[a]));if(j>=0)return j;}return -1;}
  var C={job:col(['Job Number','Reference','Job No','Job Ref']),status:col(['Status']),date:col(['Date of Enquiry','Enquiry Date']),site:col(['Site','Client']),area:col(['Area']),desc:col(['Description']),orig:col(['Originator']),sys:col(['Fergus Status','ServiceM8 Status']),link:col(['Link to job','Job Link'])};
  var sysL=C.sys>=0?colL(c0+C.sys):'',linkL=C.link>=0?colL(c0+C.link):'';
  var undatedTab=C.date<0;
  for(var i=hi+1;i<values.length;i++){
    var v=values[i];var rowNum=r0+i;
    if(RF&&(rowNum<RF||rowNum>RT))continue;
    if(RF)inRange.push({row:rowNum,jobNo:C.job>=0?S(v[C.job]):'',status:S(v[C.status]),site:C.site>=0?S(v[C.site]):'',desc:C.desc>=0?S(v[C.desc]):'',sysCell:C.sys>=0?S(v[C.sys]):''});
    if(!v.some(function(c){return S(c)!=='';}))continue;
    var st=S(v[C.status]);var map=STATUS[norm(st)];
    if(!map){count(tab+' | status '+(st||'(blank)'));continue;}
    var d=null;
    // Rows picked explicitly with rowFrom/rowTo skip the date checks.
    if(!undatedTab){d=toDate(v[C.date]);if(!RF){if(!d){count(tab+' | no date');continue;}if(d<CUTOFF){count(tab+' | before 2025');continue;}}}
    var jobNo=C.job>=0?S(v[C.job]):'';
    var ex0=jobNo?existingPO[jobNo.toLowerCase()]:null;
    if(C.sys>=0&&S(v[C.sys])==='Created'){
      if(ex0&&C.link>=0&&S(v[C.link])===''){writeOnly.push({sheetId:t.id,row:rowNum,sysCol:'',linkCol:linkL,uuid:ex0.uuid,no:ex0.no});count(tab+' | Created but link missing, link to be added');}
      else{count(tab+' | already Created on sheet');}
      continue;
    }
    var desc=S(v[C.desc]);
    if(!jobNo){problems.push(tab+' row '+rowNum+': missing job number, skipped');continue;}
    if(ex0){count(tab+' | already in ServiceM8, sheet to be marked');writeOnly.push({sheetId:t.id,row:rowNum,sysCol:sysL,linkCol:linkL,uuid:ex0.uuid,no:ex0.no});continue;}
    if(!desc){desc='No description on sheet';noDesc.push(tab+' row '+rowNum+' (job '+jobNo+')');}
    if(seen[jobNo.toLowerCase()]){problems.push(tab+' row '+rowNum+': job number '+jobNo+' duplicates '+seen[jobNo.toLowerCase()]+', skipped');continue;}
    seen[jobNo.toLowerCase()]=tab+' row '+rowNum;
    var site=C.site>=0?S(v[C.site]):'';var cname=clientName(tab,site);var ex=clients[norm(cname)];
    if(!ex)newClients[cname]=(newClients[cname]||0)+1;
    var qu=queues[norm(map[1])];if(!qu){problems.push(tab+' row '+rowNum+': no active folder '+map[1]);continue;}
    var area=C.area>=0?S(v[C.area]):'';var orig=C.orig>=0?S(v[C.orig]):'';
    var jd=jobNo+' '+desc;var det=[];if(area)det.push('Area: '+area);if(orig)det.push('Raised by: '+orig);if(det.length)jd+='\n\n'+det.join('\n');
    rows.push({tab:tab,sheetId:t.id,row:rowNum,jobNo:jobNo,sheetStatus:st,status:map[0],folder:map[1],queueUuid:qu,clientName:cname,clientUuid:ex?ex.uuid:'',jobAddress:(ex&&ex.address)?ex.address:cname,jobDescription:jd,date:d?d.toISOString().slice(0,10)+' 00:00:00':'',sysCol:sysL,linkCol:linkL});
  }
});
var byTab={},byFolder={};rows.forEach(function(x){byTab[x.tab]=(byTab[x.tab]||0)+1;byFolder[x.folder]=(byFolder[x.folder]||0)+1;});
return [{json:{total:rows.length,byTab:byTab,byFolder:byFolder,newClients:newClients,noDescription:noDesc,writeOnlyCount:writeOnly.length,skipped:skipped,problems:problems,inRange:inRange,sample:rows.slice(0,6).map(function(x){return {tab:x.tab,row:x.row,client:x.clientName,folder:x.folder,status:x.status,description:x.jobDescription};}),rows:rows,writeOnly:writeOnly}}];

var rows=$('Plan').first().json.rows||[];var names={};
rows.forEach(function(r){if(!r.clientUuid)names[r.clientName]=1;});
var list=Object.keys(names).map(function(n){return {json:{name:n}};});
return list.length?list:[{json:{skip:true}}];

var rows=$('Plan').first().json.rows||[];var made={};
try{var asked=$('Client Items').all();$('Create Client').all().forEach(function(i,idx){var u=i.json&&i.json.headers&&i.json.headers['x-record-uuid'];var n=asked[idx]&&asked[idx].json.name;if(u&&n)made[n]=u;});}catch(e){}
var exp=$now.setZone('Europe/London').plus({days:14}).toFormat('yyyy-MM-dd')+' 17:00:00';
var out=[];
rows.forEach(function(r){
  var cu=r.clientUuid||made[r.clientName];
  if(!cu)return;
  var body={active:1,status:r.status,company_uuid:cu,job_address:r.jobAddress,job_description:r.jobDescription,purchase_order_number:r.jobNo,queue_uuid:r.queueUuid,queue_expiry_date:exp};
  if(r.date)body.date=r.date;
  out.push({json:Object.assign({},r,{clientUuid:cu,body:body})});
});
return out;

var JOB_URL='https://go.servicem8.com/openjob/';
var src=$('Job Items').all();var created=$('Create Job').all();var out=[];
$input.all().forEach(function(item,i){
  var s=src[i]&&src[i].json;if(!s)return;
  var uuid=created[i]&&created[i].json&&created[i].json.headers&&created[i].json.headers['x-record-uuid'];
  if(!uuid)return;
  var no=String(item.json.generated_job_id||'');
  if(s.sysCol)out.push({json:{sheetId:s.sheetId,address:s.sysCol+s.row,field:'values',value:'Created'}});
  if(s.linkCol)out.push({json:{sheetId:s.sheetId,address:s.linkCol+s.row,field:'formulas',value:'=HYPERLINK("'+JOB_URL+uuid+'","'+(no||'Open job')+'")'}});
});
// Rows already in ServiceM8 whose sheet was never marked (e.g. throttled writes on an earlier run).
($('Plan').first().json.writeOnly||[]).forEach(function(w){
  if(w.sysCol)out.push({json:{sheetId:w.sheetId,address:w.sysCol+w.row,field:'values',value:'Created'}});
  if(w.linkCol&&w.uuid)out.push({json:{sheetId:w.sheetId,address:w.linkCol+w.row,field:'formulas',value:'=HYPERLINK("'+JOB_URL+w.uuid+'","'+(w.no||'Open job')+'")'}});
});
return out;
